export abstract class ArboxResources {
  /** Classes and sessions: the schedule, bookings, check-ins, waiting lists and trial classes. */
  readonly schedule: ScheduleResource;
  /** Members, leads and staff as Arbox users: search, profile, notes and payments. */
  readonly users: UsersResource;
  /** Members' memberships: create, update, hold, cancel and debt. */
  readonly memberships: MembershipsResource;
  /** The membership plans a studio sells, plus cancel and hold reasons. */
  readonly membershipTypes: MembershipTypesResource;
  /** Staff members and their salary report. */
  readonly staff: StaffResource;
  /** Leads: create, update status, convert or lose, and lookup lists. */
  readonly leads: LeadsResource;
  /** Staff tasks. */
  readonly tasks: TasksResource;
  /** Messages to users and message templates. */
  readonly messages: MessagesResource;
  /** The studio's locations. */
  readonly locations: LocationsResource;
  /** Custom fields defined for users and leads. */
  readonly customFields: CustomFieldsResource;
  /** Digital forms and signing links. */
  readonly digitalForms: DigitalFormsResource;
  /** Built-in Arbox reports, by report name. */
  readonly reports: ReportsResource;
  /** Finance reports and documents. */
  readonly finance: FinanceResource;

  protected constructor(transport: Transport) {
    this.schedule = new ScheduleResource(transport);
    this.users = new UsersResource(transport);
    this.memberships = new MembershipsResource(transport);
    this.membershipTypes = new MembershipTypesResource(transport);
    this.staff = new StaffResource(transport);
    this.leads = new LeadsResource(transport);
    this.tasks = new TasksResource(transport);
    this.messages = new MessagesResource(transport);
    this.locations = new LocationsResource(transport);
    this.customFields = new CustomFieldsResource(transport);
    this.digitalForms = new DigitalFormsResource(transport);
    this.reports = new ReportsResource(transport);
    this.finance = new FinanceResource(transport);
  }
}
